-- Recipe 3: exactly-one definition family
CREATE OR REPLACE FUNCTION ultimateteam.lfv4_r3_definition() RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, ultimateteam
AS $$
DECLARE
    v_id bigint;
    v_def ultimateteam.item_definitions%ROWTYPE;
    v_player boolean;
    v_manager boolean;
    v_consumable boolean;
    v_customisation boolean;
BEGIN
    IF TG_TABLE_NAME = 'item_definitions' THEN
            IF TG_OP = 'DELETE' THEN v_id := OLD.definition_id; ELSE v_id := NEW.definition_id; END IF;
    SELECT * INTO v_def FROM ultimateteam.item_definitions WHERE definition_id = v_id;
    IF NOT FOUND THEN RETURN NULL; END IF;
    ELSE
        IF TG_OP = 'DELETE' THEN v_id := OLD.definition_id; ELSE v_id := NEW.definition_id; END IF;
        IF NOT EXISTS (SELECT 1 FROM ultimateteam.player_card_definitions WHERE definition_id = v_id)
           AND NOT EXISTS (SELECT 1 FROM ultimateteam.manager_definitions WHERE definition_id = v_id)
           AND NOT EXISTS (SELECT 1 FROM ultimateteam.consumable_definitions WHERE definition_id = v_id)
           AND NOT EXISTS (SELECT 1 FROM ultimateteam.customisation_definitions WHERE definition_id = v_id) THEN RETURN NULL; END IF;
        SELECT * INTO v_def FROM ultimateteam.item_definitions WHERE definition_id = v_id FOR KEY SHARE;
        IF NOT FOUND THEN RETURN NULL; END IF;
    END IF;
    SELECT EXISTS (SELECT 1 FROM ultimateteam.player_card_definitions p WHERE p.definition_id = v_def.definition_id) INTO v_player;
    SELECT EXISTS (SELECT 1 FROM ultimateteam.manager_definitions m WHERE m.definition_id = v_def.definition_id) INTO v_manager;
    SELECT EXISTS (SELECT 1 FROM ultimateteam.consumable_definitions c WHERE c.definition_id = v_def.definition_id) INTO v_consumable;
    SELECT EXISTS (SELECT 1 FROM ultimateteam.customisation_definitions k WHERE k.definition_id = v_def.definition_id) INTO v_customisation;
    IF v_def.family_id = 1 THEN
        IF NOT (v_player AND NOT v_manager AND NOT v_consumable AND NOT v_customisation) THEN
            PERFORM ultimateteam.lfv4_err('definition ' || v_def.definition_id || ' (family 1) must have exactly the player child');
        END IF;
    ELSIF v_def.family_id = 2 THEN
        IF NOT (v_manager AND NOT v_player AND NOT v_consumable AND NOT v_customisation) THEN
            PERFORM ultimateteam.lfv4_err('definition ' || v_def.definition_id || ' (family 2) must have exactly the manager child');
        END IF;
    ELSIF v_def.family_id = 3 THEN
        IF NOT (v_consumable AND NOT v_player AND NOT v_manager AND NOT v_customisation) THEN
            PERFORM ultimateteam.lfv4_err('definition ' || v_def.definition_id || ' (family 3) must have exactly the consumable child');
        END IF;
    ELSIF v_def.family_id = 4 THEN
        IF NOT (v_customisation AND NOT v_player AND NOT v_manager AND NOT v_consumable) THEN
            PERFORM ultimateteam.lfv4_err('definition ' || v_def.definition_id || ' (family 4) must have exactly the customisation child');
        END IF;
    ELSIF v_def.family_id = 5 THEN
        IF v_player OR v_manager OR v_consumable OR v_customisation THEN
            PERFORM ultimateteam.lfv4_err('definition ' || v_def.definition_id || ' (family 5) must have none of the four definition children');
        END IF;
    ELSE
        PERFORM ultimateteam.lfv4_err('definition ' || v_def.definition_id || ' has invalid family_id ' || v_def.family_id::text);
    END IF;
    RETURN NULL; END
$$;


CREATE CONSTRAINT TRIGGER lfv4_trg_r3_item_definitions AFTER INSERT OR UPDATE OR DELETE ON ultimateteam.item_definitions DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ultimateteam.lfv4_r3_definition();
CREATE CONSTRAINT TRIGGER lfv4_trg_r3_player_card_definitions AFTER INSERT OR UPDATE OR DELETE ON ultimateteam.player_card_definitions DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ultimateteam.lfv4_r3_definition();
CREATE CONSTRAINT TRIGGER lfv4_trg_r3_manager_definitions AFTER INSERT OR UPDATE OR DELETE ON ultimateteam.manager_definitions DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ultimateteam.lfv4_r3_definition();
CREATE CONSTRAINT TRIGGER lfv4_trg_r3_consumable_definitions AFTER INSERT OR UPDATE OR DELETE ON ultimateteam.consumable_definitions DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ultimateteam.lfv4_r3_definition();
CREATE CONSTRAINT TRIGGER lfv4_trg_r3_customisation_definitions AFTER INSERT OR UPDATE OR DELETE ON ultimateteam.customisation_definitions DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ultimateteam.lfv4_r3_definition();

-- Recipe 4: exactly-one owned family
CREATE OR REPLACE FUNCTION ultimateteam.lfv4_r4_item() RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, ultimateteam
AS $$
DECLARE
    v_id bigint;
    v_item ultimateteam.items%ROWTYPE;
    v_player boolean;
    v_manager boolean;
    v_consumable boolean;
    v_customisation boolean;
    v_pick boolean;
BEGIN
    IF TG_TABLE_NAME = 'items' THEN
            IF TG_OP = 'DELETE' THEN v_id := OLD.id; ELSE v_id := NEW.id; END IF;
    SELECT * INTO v_item FROM ultimateteam.items WHERE id = v_id;
    IF NOT FOUND THEN RETURN NULL; END IF;
    ELSE
        IF TG_OP = 'DELETE' THEN v_id := OLD.item_id; ELSE v_id := NEW.item_id; END IF;
        SELECT * INTO v_item FROM ultimateteam.items WHERE id = v_id FOR KEY SHARE;
        IF NOT FOUND THEN RETURN NULL; END IF;
    END IF;
    PERFORM 1 FROM ultimateteam.item_definitions d WHERE d.definition_id = v_item.definition_id AND d.family_id = v_item.family_id FOR KEY SHARE;
    IF NOT FOUND THEN PERFORM ultimateteam.lfv4_err('item ' || v_item.id || ' family differs from its definition'); END IF;
    SELECT EXISTS (SELECT 1 FROM ultimateteam.player_items pi WHERE pi.item_id = v_item.id) INTO v_player;
    SELECT EXISTS (SELECT 1 FROM ultimateteam.manager_items mi WHERE mi.item_id = v_item.id) INTO v_manager;
    SELECT EXISTS (SELECT 1 FROM ultimateteam.consumable_items ci WHERE ci.item_id = v_item.id) INTO v_consumable;
    SELECT EXISTS (SELECT 1 FROM ultimateteam.customisation_items ki WHERE ki.item_id = v_item.id) INTO v_customisation;
    SELECT EXISTS (SELECT 1 FROM ultimateteam.player_pick_items ppi WHERE ppi.item_id = v_item.id) INTO v_pick;
    IF v_item.family_id = 1 THEN
        IF NOT (v_player AND NOT v_manager AND NOT v_consumable AND NOT v_customisation AND NOT v_pick) THEN
            PERFORM ultimateteam.lfv4_err('item ' || v_item.id || ' (family 1) must have exactly the player owned child');
        END IF;
    ELSIF v_item.family_id = 2 THEN
        IF NOT (v_manager AND NOT v_player AND NOT v_consumable AND NOT v_customisation AND NOT v_pick) THEN
            PERFORM ultimateteam.lfv4_err('item ' || v_item.id || ' (family 2) must have exactly the manager owned child');
        END IF;
    ELSIF v_item.family_id = 3 THEN
        IF NOT (v_consumable AND NOT v_player AND NOT v_manager AND NOT v_customisation AND NOT v_pick) THEN
            PERFORM ultimateteam.lfv4_err('item ' || v_item.id || ' (family 3) must have exactly the consumable owned child');
        END IF;
    ELSIF v_item.family_id = 4 THEN
        IF NOT (v_customisation AND NOT v_player AND NOT v_manager AND NOT v_consumable AND NOT v_pick) THEN
            PERFORM ultimateteam.lfv4_err('item ' || v_item.id || ' (family 4) must have exactly the customisation owned child');
        END IF;
    ELSIF v_item.family_id = 5 THEN
        IF NOT (v_pick AND NOT v_player AND NOT v_manager AND NOT v_consumable AND NOT v_customisation) THEN
            PERFORM ultimateteam.lfv4_err('item ' || v_item.id || ' (family 5) must have exactly the player-pick owned child');
        END IF;
    ELSE
        PERFORM ultimateteam.lfv4_err('item ' || v_item.id || ' has invalid family_id ' || v_item.family_id::text);
    END IF;
    RETURN NULL; END
$$;


CREATE CONSTRAINT TRIGGER lfv4_trg_r4_items AFTER INSERT OR UPDATE OR DELETE ON ultimateteam.items DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ultimateteam.lfv4_r4_item();
CREATE CONSTRAINT TRIGGER lfv4_trg_r4_player_items AFTER INSERT OR UPDATE OR DELETE ON ultimateteam.player_items DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ultimateteam.lfv4_r4_item();
CREATE CONSTRAINT TRIGGER lfv4_trg_r4_manager_items AFTER INSERT OR UPDATE OR DELETE ON ultimateteam.manager_items DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ultimateteam.lfv4_r4_item();
CREATE CONSTRAINT TRIGGER lfv4_trg_r4_consumable_items AFTER INSERT OR UPDATE OR DELETE ON ultimateteam.consumable_items DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ultimateteam.lfv4_r4_item();
CREATE CONSTRAINT TRIGGER lfv4_trg_r4_customisation_items AFTER INSERT OR UPDATE OR DELETE ON ultimateteam.customisation_items DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ultimateteam.lfv4_r4_item();
CREATE CONSTRAINT TRIGGER lfv4_trg_r4_player_pick_items AFTER INSERT OR UPDATE OR DELETE ON ultimateteam.player_pick_items DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ultimateteam.lfv4_r4_item();

-- Recipe 5: squad references
CREATE OR REPLACE FUNCTION ultimateteam.lfv4_r5_squad() RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, ultimateteam
AS $$
DECLARE
    v_id bigint;
    v_row record;
    v_squad ultimateteam.squads%ROWTYPE;
    v_squad_id bigint;
    v_ref_kind text;
    v_item_id bigint;
    v_def_id bigint;
    v_footballer_id bigint;
    v_tactic_id bigint;
    v_squad_player_id bigint;
BEGIN
    IF TG_OP = 'DELETE' THEN v_id := OLD.id; ELSE v_id := NEW.id; END IF;
    IF TG_TABLE_NAME = 'squad_players' THEN
        SELECT * INTO v_row FROM ultimateteam.squad_players WHERE id = v_id;
        IF NOT FOUND THEN RETURN NULL; END IF;
        v_squad_id := v_row.squad_id; v_ref_kind := v_row.reference_kind;
        v_item_id := v_row.item_id; v_def_id := v_row.definition_id; v_footballer_id := v_row.footballer_id;
    ELSIF TG_TABLE_NAME = 'squad_managers' THEN
        SELECT * INTO v_row FROM ultimateteam.squad_managers WHERE id = v_id;
        IF NOT FOUND THEN RETURN NULL; END IF;
        v_squad_id := v_row.squad_id; v_ref_kind := v_row.reference_kind;
        v_item_id := v_row.item_id; v_def_id := v_row.definition_id;
    ELSIF TG_TABLE_NAME = 'squad_roles' THEN
        SELECT * INTO v_row FROM ultimateteam.squad_roles WHERE id = v_id;
        IF NOT FOUND THEN RETURN NULL; END IF;
        v_squad_id := v_row.squad_id; v_squad_player_id := v_row.squad_player_id;
    ELSE
        SELECT * INTO v_row FROM ultimateteam.squad_tactic_instructions WHERE id = v_id;
        IF NOT FOUND THEN RETURN NULL; END IF;
        v_tactic_id := v_row.tactic_id; v_squad_player_id := v_row.squad_player_id;
    END IF;
    IF TG_TABLE_NAME IN ('squad_players', 'squad_managers') THEN
        SELECT * INTO v_squad FROM ultimateteam.squads WHERE id = v_squad_id FOR KEY SHARE;
        IF NOT FOUND THEN
            PERFORM ultimateteam.lfv4_err('squad ' || v_squad_id || ' does not exist');
        END IF;
    END IF;
    IF TG_TABLE_NAME = 'squad_players' THEN
        IF NOT EXISTS (
            SELECT 1 FROM ultimateteam.player_card_definitions d
            WHERE d.definition_id = v_def_id AND d.footballer_id = v_footballer_id
        ) THEN
            PERFORM ultimateteam.lfv4_err('squad player ' || v_id || ' definition does not declare footballer ' || v_footballer_id::text);
        END IF;
        IF v_ref_kind = 'owned' AND EXISTS (
            SELECT 1 FROM ultimateteam.player_items pi WHERE pi.item_id = v_item_id
        ) AND NOT EXISTS (
            SELECT 1
            FROM ultimateteam.player_items pi
            JOIN ultimateteam.items i ON i.id = pi.item_id
            WHERE pi.item_id = v_item_id
              AND i.club_id = v_squad.club_id
              AND i.definition_id = v_def_id
            FOR KEY SHARE
        ) THEN
            PERFORM ultimateteam.lfv4_err('squad player ' || v_id || ' owned item does not match squad club and definition');
        END IF;
    ELSIF TG_TABLE_NAME = 'squad_managers' THEN
        IF v_ref_kind = 'owned' AND EXISTS (
            SELECT 1 FROM ultimateteam.manager_items mi WHERE mi.item_id = v_item_id
        ) AND NOT EXISTS (
            SELECT 1
            FROM ultimateteam.manager_items mi
            JOIN ultimateteam.items i ON i.id = mi.item_id
            WHERE mi.item_id = v_item_id
              AND i.club_id = v_squad.club_id
              AND i.definition_id = v_def_id
            FOR KEY SHARE
        ) THEN
            PERFORM ultimateteam.lfv4_err('squad manager ' || v_id || ' owned item does not match squad club and definition');
        END IF;
    ELSIF TG_TABLE_NAME = 'squad_roles' THEN
        IF NOT EXISTS (
            SELECT 1 FROM ultimateteam.squad_players sp
            WHERE sp.id = v_squad_player_id AND sp.squad_id = v_squad_id
        ) THEN
            PERFORM ultimateteam.lfv4_err('squad role ' || v_id || ' references a squad player outside its squad');
        END IF;
    ELSE
        IF v_squad_player_id IS NOT NULL AND NOT EXISTS (
            SELECT 1
            FROM ultimateteam.squad_players sp
            JOIN ultimateteam.squad_tactics st ON st.squad_id = sp.squad_id
            WHERE sp.id = v_squad_player_id AND st.id = v_tactic_id
        ) THEN
            PERFORM ultimateteam.lfv4_err('squad tactic instruction ' || v_id || ' references a squad player outside the tactic squad');
        END IF;
    END IF;
    RETURN NULL; END
$$;


CREATE CONSTRAINT TRIGGER lfv4_trg_r5_squad_players AFTER INSERT OR UPDATE OR DELETE ON ultimateteam.squad_players DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ultimateteam.lfv4_r5_squad();
CREATE CONSTRAINT TRIGGER lfv4_trg_r5_squad_managers AFTER INSERT OR UPDATE OR DELETE ON ultimateteam.squad_managers DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ultimateteam.lfv4_r5_squad();
CREATE CONSTRAINT TRIGGER lfv4_trg_r5_squad_roles AFTER INSERT OR UPDATE OR DELETE ON ultimateteam.squad_roles DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ultimateteam.lfv4_r5_squad();
CREATE CONSTRAINT TRIGGER lfv4_trg_r5_squad_tactic_instructions AFTER INSERT OR UPDATE OR DELETE ON ultimateteam.squad_tactic_instructions DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ultimateteam.lfv4_r5_squad();

-- Recipe 6: customization references
CREATE OR REPLACE FUNCTION ultimateteam.lfv4_r6_club_slot_bindings() RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, ultimateteam
AS $$
DECLARE
    v_id bigint;
    v_row ultimateteam.club_slot_bindings%ROWTYPE;
    v_def ultimateteam.item_definitions%ROWTYPE;
    v_slot_item_type text;
    v_slot_native_subtype bigint;
BEGIN
        IF TG_OP = 'DELETE' THEN v_id := OLD.id; ELSE v_id := NEW.id; END IF;
    SELECT * INTO v_row FROM ultimateteam.club_slot_bindings WHERE id = v_id;
    IF NOT FOUND THEN RETURN NULL; END IF;
    SELECT d.* INTO v_def FROM ultimateteam.item_definitions d JOIN ultimateteam.customisation_definitions c ON c.definition_id = d.definition_id WHERE d.definition_id = v_row.definition_id;
    IF NOT FOUND THEN
        PERFORM ultimateteam.lfv4_err('club slot binding ' || v_row.id || ' references missing customisation definition ' || v_row.definition_id::text);
    END IF;
    IF v_row.reference_kind = 'owned' AND EXISTS (
        SELECT 1 FROM ultimateteam.customisation_items ki WHERE ki.item_id = v_row.item_id
    ) AND NOT EXISTS (
        SELECT 1
        FROM ultimateteam.customisation_items ki
        JOIN ultimateteam.items i ON i.id = ki.item_id
        WHERE ki.item_id = v_row.item_id
          AND i.club_id = v_row.club_id
          AND i.definition_id = v_row.definition_id
        FOR KEY SHARE
    ) THEN
        PERFORM ultimateteam.lfv4_err('club slot binding ' || v_row.id || ' owned item does not match club and definition');
    END IF;
    SELECT v.item_type, v.native_subtype INTO v_slot_item_type, v_slot_native_subtype
    FROM (VALUES
(3, 'kit', 9),
                (4, 'kit', 9),
                (2, 'custom', 11),
                (1, 'ball', 30),
                (5, 'stadium', 10),
                (6, 'tifo_basic', 10),
                (7, 'tifo_animated', 10),
                (8, 'tifo_standard', 10),
                (9, 'stadium_theme', 10),
                (10, 'tifo_background', 10),
                (11, 'pitch_line_colour', 10),
                (12, 'pitch_mow_pattern', 10),
                (13, 'pitch_chair_colour', 10),
                (14, 'pitch_goal_colour', 10),
                (15, 'goalceleb_cannon_flame', 10)
        ) v(slot_id, item_type, native_subtype)
    WHERE v.slot_id = v_row.slot_id;
    IF NOT FOUND THEN
        PERFORM ultimateteam.lfv4_err('club slot binding ' || v_row.id || ' has unknown slot_id ' || v_row.slot_id::text);
    END IF;
    IF v_def.native_item_type IS DISTINCT FROM v_slot_item_type
       OR v_def.native_subtype IS DISTINCT FROM v_slot_native_subtype THEN
        PERFORM ultimateteam.lfv4_err('club slot binding ' || v_row.id || ' definition type/subtype does not match slot ' || v_row.slot_id::text);
    END IF;
    RETURN NULL; END
$$;


CREATE OR REPLACE FUNCTION ultimateteam.lfv4_r6_onboarding_kit_choices() RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, ultimateteam
AS $$
DECLARE
    v_id bigint;
    v_row ultimateteam.onboarding_kit_choices%ROWTYPE;
    v_def ultimateteam.item_definitions%ROWTYPE;
BEGIN
        IF TG_OP = 'DELETE' THEN v_id := OLD.id; ELSE v_id := NEW.id; END IF;
    SELECT * INTO v_row FROM ultimateteam.onboarding_kit_choices WHERE id = v_id;
    IF NOT FOUND THEN RETURN NULL; END IF;
    SELECT d.* INTO v_def FROM ultimateteam.item_definitions d JOIN ultimateteam.customisation_definitions c ON c.definition_id = d.definition_id WHERE d.definition_id = v_row.definition_id;
    IF NOT FOUND THEN
        PERFORM ultimateteam.lfv4_err('onboarding kit choice ' || v_row.id || ' references missing customisation definition ' || v_row.definition_id::text);
    END IF;
    IF v_def.native_item_type IS DISTINCT FROM 'kit' THEN
        PERFORM ultimateteam.lfv4_err('onboarding kit choice ' || v_row.id || ' definition is not a kit');
    END IF;
    IF v_row.item_id IS NOT NULL AND EXISTS (
        SELECT 1 FROM ultimateteam.customisation_items ki WHERE ki.item_id = v_row.item_id
    ) AND NOT EXISTS (
        SELECT 1
        FROM ultimateteam.customisation_items ki
        JOIN ultimateteam.items i ON i.id = ki.item_id
        WHERE ki.item_id = v_row.item_id
          AND i.club_id = v_row.club_id
          AND i.definition_id = v_row.definition_id
        FOR KEY SHARE
    ) THEN
        PERFORM ultimateteam.lfv4_err('onboarding kit choice ' || v_row.id || ' owned item does not match club and definition');
    END IF;
    RETURN NULL; END
$$;


CREATE CONSTRAINT TRIGGER lfv4_trg_r6_club_slot_bindings AFTER INSERT OR UPDATE OR DELETE ON ultimateteam.club_slot_bindings DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ultimateteam.lfv4_r6_club_slot_bindings();
CREATE CONSTRAINT TRIGGER lfv4_trg_r6_onboarding_kit_choices AFTER INSERT OR UPDATE OR DELETE ON ultimateteam.onboarding_kit_choices DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ultimateteam.lfv4_r6_onboarding_kit_choices();

-- Recipe 7: player style and selected pick
CREATE OR REPLACE FUNCTION ultimateteam.lfv4_r7_style_pick() RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, ultimateteam
AS $$
DECLARE
    v_id bigint;
    v_row record;
    v_item_id bigint;
    v_style_id bigint;
    v_selected_id bigint;
BEGIN
    IF TG_OP = 'DELETE' THEN v_id := OLD.item_id; ELSE v_id := NEW.item_id; END IF;
    IF TG_TABLE_NAME = 'player_items' THEN
        SELECT * INTO v_row FROM ultimateteam.player_items WHERE item_id = v_id;
        IF NOT FOUND THEN RETURN NULL; END IF;
        v_item_id := v_row.item_id; v_style_id := v_row.style_definition_id;
        IF v_style_id IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM ultimateteam.consumable_definitions cd
            WHERE cd.definition_id = v_style_id AND cd.consumable_kind = 'chemistry_style'
        ) THEN
            PERFORM ultimateteam.lfv4_err('player item ' || v_item_id || ' style definition is not a chemistry_style consumable');
        END IF;
    ELSE
        SELECT * INTO v_row FROM ultimateteam.player_pick_items WHERE item_id = v_id;
        IF NOT FOUND THEN RETURN NULL; END IF;
        v_item_id := v_row.item_id; v_selected_id := v_row.selected_choice_id;
        IF v_selected_id IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM ultimateteam.player_pick_choices pc
            WHERE pc.id = v_selected_id AND pc.token_item_id = v_item_id FOR KEY SHARE
        ) THEN
            PERFORM ultimateteam.lfv4_err('player pick item ' || v_item_id || ' selected choice does not belong to the token item');
        END IF;
    END IF;
    RETURN NULL; END
$$;


CREATE CONSTRAINT TRIGGER lfv4_trg_r7_player_items AFTER INSERT OR UPDATE OR DELETE ON ultimateteam.player_items DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ultimateteam.lfv4_r7_style_pick();
CREATE CONSTRAINT TRIGGER lfv4_trg_r7_player_pick_items AFTER INSERT OR UPDATE OR DELETE ON ultimateteam.player_pick_items DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ultimateteam.lfv4_r7_style_pick();

-- Recipe 8: active market ownership and snapshot agreement
CREATE OR REPLACE FUNCTION ultimateteam.lfv4_r8_listing() RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, ultimateteam
AS $$
DECLARE
    v_id bigint;
    v_row ultimateteam.market_listings%ROWTYPE;
BEGIN
        IF TG_OP = 'DELETE' THEN v_id := OLD.trade_id; ELSE v_id := NEW.trade_id; END IF;
    SELECT * INTO v_row FROM ultimateteam.market_listings WHERE trade_id = v_id;
    IF NOT FOUND THEN RETURN NULL; END IF;
    IF v_row.kind = 'player' AND v_row.state = 'active' AND NOT EXISTS (
        SELECT 1
        FROM ultimateteam.items i
        JOIN ultimateteam.player_items pi ON pi.item_id = i.id
        WHERE i.club_id = v_row.seller_club_id
          AND i.native_item_id = v_row.seller_item_id
          AND i.definition_id = v_row.definition_id
        FOR KEY SHARE
    ) THEN
        PERFORM ultimateteam.lfv4_err('active market listing ' || v_row.trade_id || ' has no matching owned seller item');
    END IF;
    IF NOT EXISTS (SELECT 1 FROM ultimateteam.market_item_snapshots s WHERE s.trade_id = v_row.trade_id) THEN
        PERFORM ultimateteam.lfv4_err('market listing ' || v_row.trade_id || ' has no item snapshot');
    END IF;
    IF NOT EXISTS (SELECT 1 FROM ultimateteam.market_player_snapshots s WHERE s.trade_id = v_row.trade_id) THEN
        PERFORM ultimateteam.lfv4_err('market listing ' || v_row.trade_id || ' has no player snapshot');
    END IF;
    RETURN NULL; END
$$;


CREATE OR REPLACE FUNCTION ultimateteam.lfv4_r8_items() RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, ultimateteam
AS $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM ultimateteam.market_listings ml
        WHERE ml.kind = 'player' AND ml.state = 'active'
          AND ml.seller_club_id = OLD.club_id AND ml.seller_item_id = OLD.native_item_id
    ) THEN
        PERFORM ultimateteam.lfv4_err('active market listing still references deleted item club ' || OLD.club_id::text || ' native ' || OLD.native_item_id::text);
    END IF;
    RETURN NULL; END
$$;


CREATE OR REPLACE FUNCTION ultimateteam.lfv4_r8_item_snapshot() RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, ultimateteam
AS $$
DECLARE
    v_id bigint;
    v_snap ultimateteam.market_item_snapshots%ROWTYPE;
    v_listing ultimateteam.market_listings%ROWTYPE;
BEGIN
        IF TG_OP = 'DELETE' THEN v_id := OLD.trade_id; ELSE v_id := NEW.trade_id; END IF;
    SELECT * INTO v_snap FROM ultimateteam.market_item_snapshots WHERE trade_id = v_id;
    IF NOT FOUND THEN RETURN NULL; END IF;
    SELECT * INTO v_listing FROM ultimateteam.market_listings WHERE trade_id = v_snap.trade_id FOR KEY SHARE;
    IF NOT FOUND THEN RETURN NULL; END IF;
    IF NOT EXISTS (
        SELECT 1
        FROM ultimateteam.item_definitions d
        JOIN ultimateteam.player_card_definitions pcd ON pcd.definition_id = d.definition_id
        JOIN ultimateteam.card_types ct ON ct.card_type_id = pcd.card_type_id
        WHERE d.definition_id = v_listing.definition_id
          AND v_snap.definition_id = v_listing.definition_id
          AND v_snap.definition_revision = d.revision
          AND v_listing.resource_id IS NOT DISTINCT FROM d.native_resource_id
          AND v_listing.rating = pcd.rating
          AND v_listing.asset_id IS NOT DISTINCT FROM d.native_asset_id
          AND v_listing.nation_id IS NOT DISTINCT FROM pcd.native_nation_id
          AND v_listing.league_id IS NOT DISTINCT FROM pcd.native_league_id
          AND v_listing.team_id IS NOT DISTINCT FROM pcd.native_team_id
          AND v_listing.preferred_position IS NOT DISTINCT FROM pcd.position
          AND v_listing.rareflag IS NOT DISTINCT FROM ct.native_rareflag
          AND v_listing.is_special IS NOT DISTINCT FROM ct.is_special
    ) THEN
        PERFORM ultimateteam.lfv4_err('market item snapshot of trade ' || v_snap.trade_id || ' does not agree with its listing and definition');
    END IF;
    RETURN NULL; END
$$;


CREATE OR REPLACE FUNCTION ultimateteam.lfv4_r8_player_snapshot() RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, ultimateteam
AS $$
DECLARE
    v_id bigint;
    v_snap ultimateteam.market_player_snapshots%ROWTYPE;
BEGIN
        IF TG_OP = 'DELETE' THEN v_id := OLD.trade_id; ELSE v_id := NEW.trade_id; END IF;
    SELECT * INTO v_snap FROM ultimateteam.market_player_snapshots WHERE trade_id = v_id;
    IF NOT FOUND THEN RETURN NULL; END IF;
    IF NOT EXISTS (SELECT 1 FROM ultimateteam.market_item_snapshots s WHERE s.trade_id = v_snap.trade_id FOR KEY SHARE) THEN
        PERFORM ultimateteam.lfv4_err('market player snapshot of trade ' || v_snap.trade_id || ' has no item snapshot parent');
    END IF;
    IF v_snap.style_definition_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM ultimateteam.consumable_definitions cd
        WHERE cd.definition_id = v_snap.style_definition_id AND cd.consumable_kind = 'chemistry_style'
    ) THEN
        PERFORM ultimateteam.lfv4_err('market player snapshot of trade ' || v_snap.trade_id || ' style definition is not a chemistry_style consumable');
    END IF;
    RETURN NULL; END
$$;


CREATE CONSTRAINT TRIGGER lfv4_trg_r8_market_listings AFTER INSERT OR UPDATE OR DELETE ON ultimateteam.market_listings DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ultimateteam.lfv4_r8_listing();
CREATE CONSTRAINT TRIGGER lfv4_trg_r8_items AFTER DELETE ON ultimateteam.items DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ultimateteam.lfv4_r8_items();
CREATE CONSTRAINT TRIGGER lfv4_trg_r8_market_item_snapshots AFTER INSERT OR UPDATE OR DELETE ON ultimateteam.market_item_snapshots DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ultimateteam.lfv4_r8_item_snapshot();
CREATE CONSTRAINT TRIGGER lfv4_trg_r8_market_player_snapshots AFTER INSERT OR UPDATE OR DELETE ON ultimateteam.market_player_snapshots DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ultimateteam.lfv4_r8_player_snapshot();

-- Recipe 9: immutable published snapshot state
CREATE OR REPLACE FUNCTION ultimateteam.lfv4_r9_item_snapshots() RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, ultimateteam
AS $$
DECLARE
    v_id bigint;
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.creation_transaction_id IS DISTINCT FROM pg_catalog.pg_current_xact_id() THEN
            PERFORM ultimateteam.lfv4_err('invalid snapshot creation transaction');
        END IF;
        RETURN NEW;
    END IF;
    v_id := OLD.trade_id;
    IF TG_OP = 'DELETE' AND NOT EXISTS (SELECT 1 FROM ultimateteam.market_listings WHERE trade_id = v_id) THEN
        RETURN OLD;
    END IF;
    IF OLD.creation_transaction_id IS DISTINCT FROM pg_catalog.pg_current_xact_id() THEN
        PERFORM ultimateteam.lfv4_err('published market snapshot is immutable');
    END IF;
    IF TG_OP = 'UPDATE' AND NEW.creation_transaction_id IS DISTINCT FROM OLD.creation_transaction_id THEN
        PERFORM ultimateteam.lfv4_err('snapshot creation transaction cannot change');
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END
$$;


CREATE OR REPLACE FUNCTION ultimateteam.lfv4_r9_snapshot_children() RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, ultimateteam
AS $$
DECLARE
    v_id bigint;
    v_creation xid8;
BEGIN
    IF TG_OP = 'DELETE' THEN v_id := OLD.trade_id; ELSE v_id := NEW.trade_id; END IF;
    IF TG_OP = 'UPDATE' AND NEW.trade_id IS DISTINCT FROM OLD.trade_id THEN
        PERFORM ultimateteam.lfv4_err('snapshot child cannot change parent');
    END IF;
    IF TG_OP = 'DELETE' AND NOT EXISTS (SELECT 1 FROM ultimateteam.market_listings WHERE trade_id = v_id) THEN
        RETURN OLD;
    END IF;
    SELECT creation_transaction_id INTO v_creation FROM ultimateteam.market_item_snapshots WHERE trade_id = v_id FOR KEY SHARE;
    IF NOT FOUND OR v_creation IS DISTINCT FROM pg_catalog.pg_current_xact_id() THEN
        PERFORM ultimateteam.lfv4_err('published snapshot child is immutable or parent is missing');
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END
$$;


CREATE TRIGGER lfv4_trg_r9_market_item_snapshots BEFORE INSERT OR UPDATE OR DELETE ON ultimateteam.market_item_snapshots FOR EACH ROW EXECUTE FUNCTION ultimateteam.lfv4_r9_item_snapshots();
CREATE TRIGGER lfv4_trg_r9_market_player_snapshots BEFORE INSERT OR UPDATE OR DELETE ON ultimateteam.market_player_snapshots FOR EACH ROW EXECUTE FUNCTION ultimateteam.lfv4_r9_snapshot_children();
CREATE TRIGGER lfv4_trg_r9_market_player_stat_values BEFORE INSERT OR UPDATE OR DELETE ON ultimateteam.market_player_stat_values FOR EACH ROW EXECUTE FUNCTION ultimateteam.lfv4_r9_snapshot_children();
CREATE TRIGGER lfv4_trg_r9_market_player_attribute_overrides BEFORE INSERT OR UPDATE OR DELETE ON ultimateteam.market_player_attribute_overrides FOR EACH ROW EXECUTE FUNCTION ultimateteam.lfv4_r9_snapshot_children();

-- Recipe 10: draft player identity and typed overrides
-- Attribute-code set for player_attribute_overrides and
-- market_player_attribute_overrides: exactly the 35 detailed attribute columns
-- on player_card_definitions (acceleration through gk_positioning).
CREATE OR REPLACE FUNCTION ultimateteam.lfv4_attr_code_allowed(code text) RETURNS boolean
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog
AS $$
    SELECT code IN ('acceleration', 'sprint_speed', 'positioning', 'finishing', 'shot_power', 'long_shots', 'volleys', 'penalties', 'vision', 'crossing', 'free_kick_accuracy', 'short_passing', 'long_passing', 'curve', 'agility', 'balance', 'reactions', 'ball_control', 'dribbling', 'composure', 'interceptions', 'heading_accuracy', 'marking', 'standing_tackle', 'sliding_tackle', 'jumping', 'stamina', 'strength', 'aggression', 'gk_diving', 'gk_handling', 'gk_kicking', 'gk_reflexes', 'gk_speed', 'gk_positioning');
$$;


CREATE OR REPLACE FUNCTION ultimateteam.lfv4_r10_draft() RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, ultimateteam
AS $$
DECLARE
    v_id bigint;
    v_row record;
    v_kind text;
    v_def_id bigint;
    v_footballer_id bigint;
    v_code text;
BEGIN
    IF TG_OP = 'DELETE' THEN v_id := OLD.id; ELSE v_id := NEW.id; END IF;
    IF TG_TABLE_NAME = 'draft_picks' THEN
        SELECT * INTO v_row FROM ultimateteam.draft_picks WHERE id = v_id;
        IF NOT FOUND THEN RETURN NULL; END IF;
        v_kind := v_row.pick_kind; v_def_id := v_row.definition_id; v_footballer_id := v_row.footballer_id;
        IF v_kind NOT IN ('player', 'manager') THEN PERFORM ultimateteam.lfv4_err('invalid Draft kind'); END IF;
        IF v_kind = 'player' AND (v_footballer_id IS NULL OR NOT EXISTS (
            SELECT 1 FROM ultimateteam.player_card_definitions d
            WHERE d.definition_id = v_def_id AND d.footballer_id = v_footballer_id
        )) THEN
            PERFORM ultimateteam.lfv4_err('draft pick ' || v_id || ' player kind requires a matching player card definition');
        END IF;
        IF v_kind = 'manager' AND (v_footballer_id IS NOT NULL OR NOT EXISTS (
            SELECT 1 FROM ultimateteam.manager_definitions d WHERE d.definition_id = v_def_id
        )) THEN
            PERFORM ultimateteam.lfv4_err('draft pick ' || v_id || ' manager kind requires a manager definition and null footballer');
        END IF;
    ELSIF TG_TABLE_NAME = 'draft_choices' THEN
        SELECT * INTO v_row FROM ultimateteam.draft_choices WHERE id = v_id;
        IF NOT FOUND THEN RETURN NULL; END IF;
        v_kind := v_row.choice_kind; v_def_id := v_row.definition_id; v_footballer_id := v_row.footballer_id;
        IF v_kind NOT IN ('player', 'manager') THEN PERFORM ultimateteam.lfv4_err('invalid Draft kind'); END IF;
        IF v_kind = 'player' AND (v_footballer_id IS NULL OR NOT EXISTS (
            SELECT 1 FROM ultimateteam.player_card_definitions d
            WHERE d.definition_id = v_def_id AND d.footballer_id = v_footballer_id
        )) THEN
            PERFORM ultimateteam.lfv4_err('draft choice ' || v_id || ' player kind requires a matching player card definition');
        END IF;
        IF v_kind = 'manager' AND (v_footballer_id IS NOT NULL OR NOT EXISTS (
            SELECT 1 FROM ultimateteam.manager_definitions d WHERE d.definition_id = v_def_id
        )) THEN
            PERFORM ultimateteam.lfv4_err('draft choice ' || v_id || ' manager kind requires a manager definition and null footballer');
        END IF;
    ELSIF TG_TABLE_NAME = 'player_attribute_overrides' THEN
        SELECT * INTO v_row FROM ultimateteam.player_attribute_overrides WHERE id = v_id;
        IF NOT FOUND THEN RETURN NULL; END IF;
        v_code := v_row.attribute_code;
        IF NOT ultimateteam.lfv4_attr_code_allowed(v_code) THEN
            PERFORM ultimateteam.lfv4_err('player attribute override ' || v_id || ' has unknown attribute code ' || v_code);
        END IF;
    ELSE
        SELECT * INTO v_row FROM ultimateteam.market_player_attribute_overrides WHERE id = v_id;
        IF NOT FOUND THEN RETURN NULL; END IF;
        v_code := v_row.attribute_code;
        IF NOT ultimateteam.lfv4_attr_code_allowed(v_code) THEN
            PERFORM ultimateteam.lfv4_err('market player attribute override ' || v_id || ' has unknown attribute code ' || v_code);
        END IF;
    END IF;
    RETURN NULL; END
$$;


CREATE CONSTRAINT TRIGGER lfv4_trg_r10_draft_picks AFTER INSERT OR UPDATE OR DELETE ON ultimateteam.draft_picks DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ultimateteam.lfv4_r10_draft();
CREATE CONSTRAINT TRIGGER lfv4_trg_r10_draft_choices AFTER INSERT OR UPDATE OR DELETE ON ultimateteam.draft_choices DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ultimateteam.lfv4_r10_draft();
CREATE CONSTRAINT TRIGGER lfv4_trg_r10_player_attribute_overrides AFTER INSERT OR UPDATE OR DELETE ON ultimateteam.player_attribute_overrides DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ultimateteam.lfv4_r10_draft();
CREATE CONSTRAINT TRIGGER lfv4_trg_r10_market_player_attribute_overrides AFTER INSERT OR UPDATE OR DELETE ON ultimateteam.market_player_attribute_overrides DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ultimateteam.lfv4_r10_draft();
